// The SDK's database upgrades in place on its users' devices: every
// version must migrate to every later one, keeping the cache. Generated by
// `drift_dev make-migrations` (conventions §11.28), then filled in with
// real rows.
import 'package:drift/drift.dart';
import 'package:drift_dev/api/migrations_native.dart';
import 'package:flagkit/src/storage/flagkit_database.dart';
import 'package:flutter_test/flutter_test.dart';

import 'generated/schema.dart';

import 'generated/schema_v1.dart' as v1;
import 'generated/schema_v2.dart' as v2;
import 'generated/schema_v3.dart' as v3;

void main() {
  driftRuntimeOptions.dontWarnAboutMultipleDatabases = true;
  late SchemaVerifier verifier;

  setUpAll(() {
    verifier = SchemaVerifier(GeneratedHelper());
  });

  group('simple database migrations', () {
    // These simple tests verify all possible schema updates with a simple (no
    // data) migration. This is a quick way to ensure that written database
    // migrations properly alter the schema.
    const versions = GeneratedHelper.versions;
    for (final (i, fromVersion) in versions.indexed) {
      group('from $fromVersion', () {
        for (final toVersion in versions.skip(i + 1)) {
          test('to $toVersion', () async {
            final schema = await verifier.schemaAt(fromVersion);
            final db = FlagKitDatabase(schema.newConnection());
            await verifier.migrateAndValidate(db, toVersion);
            await db.close();
          });
        }
      });
    }
  });

  // The upgrade that matters: a device with cached flags must keep every
  // one of them, its anonymous id, and when they were fetched.
  test('v1 → v2 keeps the cached flags and the meta', () async {
    const flags = [
      v1.FlagsData(
        key: 'new_home_screen',
        type: 'boolean',
        value: 'true',
        offValue: 'false',
        enabled: 1,
        rules: '[]',
        updatedAt: '2026-11-04T09:41:00.000Z',
      ),
      v1.FlagsData(
        key: 'home_config',
        type: 'json',
        value: '{"banner":"Sale"}',
        offValue: '{}',
        enabled: 0,
        rolloutBp: 2500,
        rules: '[]',
        updatedAt: '2026-11-04T09:41:00.000Z',
      ),
    ];
    const meta = [
      v1.MetaData(name: 'anonymous_id', value: 'anon-1'),
      v1.MetaData(name: 'fetched_at', value: '2026-11-04T09:41:00.000Z'),
      v1.MetaData(name: 'config_version', value: '7'),
    ];

    await verifier.testWithDataIntegrity(
      oldVersion: 1,
      newVersion: 2,
      createOld: v1.DatabaseAtV1.new,
      createNew: v2.DatabaseAtV2.new,
      openTestedDatabase: FlagKitDatabase.new,
      createItems: (batch, oldDb) {
        batch
          ..insertAll(oldDb.flags, flags)
          ..insertAll(oldDb.meta, meta);
      },
      validateItems: (newDb) async {
        expect(
          [
            for (final row in await newDb.select(newDb.flags).get())
              row.toJson(),
          ],
          [for (final row in flags) row.toJson()],
        );
        expect(
          [
            for (final row in await newDb.select(newDb.meta).get())
              row.toJson(),
          ],
          [for (final row in meta) row.toJson()],
        );
        expect(await newDb.select(newDb.refreshes).get(), isEmpty);
      },
    );
  });

  // Phase 5: a device with cached flags and a refresh log keeps both, and
  // starts with no overrides.
  test('v2 → v3 keeps the flags, the meta and the log', () async {
    const flags = [
      v2.FlagsData(
        key: 'new_checkout',
        type: 'boolean',
        value: 'true',
        offValue: 'false',
        enabled: 1,
        rolloutBp: 2500,
        rules: '[{"attribute":"country","operator":"in","values":["PK"]}]',
        updatedAt: '2026-11-04T09:41:00.000Z',
      ),
    ];
    const meta = [
      v2.MetaData(name: 'anonymous_id', value: 'anon-1'),
      v2.MetaData(name: 'config_version', value: '2'),
    ];
    const log = [
      v2.RefreshesData(
        id: 1,
        trigger: 'startup',
        startedAt: '2026-11-04T09:41:00.000Z',
        finishedAt: '2026-11-04T09:41:01.000Z',
        outcome: 'updated',
        added: 1,
        changed: 0,
        removed: 0,
        skipped: 0,
        configVersion: 2,
      ),
    ];

    await verifier.testWithDataIntegrity(
      oldVersion: 2,
      newVersion: 3,
      createOld: v2.DatabaseAtV2.new,
      createNew: v3.DatabaseAtV3.new,
      openTestedDatabase: FlagKitDatabase.new,
      createItems: (batch, oldDb) {
        batch
          ..insertAll(oldDb.flags, flags)
          ..insertAll(oldDb.meta, meta)
          ..insertAll(oldDb.refreshes, log);
      },
      validateItems: (newDb) async {
        expect(
          [
            for (final row in await newDb.select(newDb.flags).get())
              row.toJson(),
          ],
          [for (final row in flags) row.toJson()],
        );
        expect(
          [
            for (final row in await newDb.select(newDb.meta).get())
              row.toJson(),
          ],
          [for (final row in meta) row.toJson()],
        );
        expect(
          [
            for (final row in await newDb.select(newDb.refreshes).get())
              row.toJson(),
          ],
          [for (final row in log) row.toJson()],
        );
        expect(await newDb.select(newDb.overrides).get(), isEmpty);
      },
    );
  });
}
